import java.awt.*;import java.awt.image.*;
/* Deterministic 64x48 palette fixtures (seed 115), with interlace off/on. */
public class GifRaster115 {
 static byte[] bytes(String s){byte[] p=new byte[s.length()/2];for(int n=0;n<p.length;n++)p[n]=(byte)Integer.parseInt(s.substring(n*2,n*2+2),16);return p;}
 public static void main(String[] a){try{Frame f=new Frame();f.show();String[] fixtures={"",""};
 for(int n=0;n<fixtures.length;n++){Image src=Toolkit.getDefaultToolkit().createImage(bytes(fixtures[n]));MediaTracker t=new MediaTracker(f);t.addImage(src,1);t.waitForAll();if(t.isErrorAny())throw new RuntimeException("GIF "+n);
 Image image=f.createImage(64,48);Graphics g=image.getGraphics();g.setColor(Color.white);g.fillRect(0,0,64,48);g.drawImage(src,0,0,null);g.dispose();int[] p=new int[64*48];if(!new PixelGrabber(image,0,0,64,48,p,0,64).grabPixels(5000))throw new RuntimeException("pixels");if(a.length>0 && a[0].equals("rgb")){int[] raw=new int[p.length];if(!new PixelGrabber(src,0,0,64,48,raw,0,64).grabPixels(5000))throw new RuntimeException("source pixels");for(int j=0;j<p.length;j++)if((p[j]&0xffffff)!=((raw[j]>>>24)==0?0xffffff:raw[j]&0xffffff))throw new RuntimeException("RGB pixel "+j);}int hash=0;for(int j=0;j<p.length;j++)hash=hash*31+(p[j]&0xffffff);System.out.println("GIF "+n+" "+hash);image.flush();src.flush();System.gc();}
 f.dispose();System.out.println("interlaced and non-interlaced GIF LZW dictionary drawing passed");System.exit(0);
 }catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
